from pathlib import Path
p=Path('outputs/index.html');s=p.read_text(encoding='utf-8')
s=s.replace('<div class="turnbar" id="turnbar">','<div class="turnbar hidden" id="turnbar">')
s=s.replace('<div class="controls moveControls" id="moveControls"','<div class="controls moveControls" id="moveControls" style="display:none"')
css='''.turnbar{margin-top:12px;padding:13px 16px;border:1px solid #355264;background:linear-gradient(110deg,#10202b,#0b151e);display:flex;align-items:center;justify-content:space-between;gap:16px}.turncopy{display:grid;gap:4px}.turncopy strong{font:700 21px 'Barlow Condensed',sans-serif;letter-spacing:.04em;color:#f0f7fa}.turncopy>span:last-child{font-size:10px;color:#a4b6c0;line-height:1.5}.turnclock{width:100px;flex:none;text-align:center}.turnclock>span{font:800 30px 'Barlow Condensed',sans-serif;color:var(--amber)}.turnclock small{display:block;margin-top:4px;color:var(--muted);font-size:8px;letter-spacing:.12em}.clockrail{height:4px;background:#29343d;margin-top:4px}.clockrail i{height:100%;display:block;background:var(--amber);transition:width .15s linear}.moveControls{display:none!important;grid-template-columns:minmax(0,1fr) 190px;gap:14px;padding:15px;border:1px solid var(--line);background:#0d1722}.moveChoices{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;align-items:stretch}.moveChoices>.eyebrow{grid-column:1/-1}.moveChoices .control{min-height:82px;text-align:left;line-height:1.5;font-size:10px}.moveChoices .control strong{font-size:18px}.destination{display:grid;gap:6px;justify-items:center;border-left:1px solid var(--line);padding-left:14px}.destination>.eyebrow{justify-self:start}.dirgrid{display:grid;grid-template-columns:repeat(3,48px);grid-template-rows:repeat(3,42px);gap:3px;align-items:center;justify-items:center}.dirgrid button{width:48px;height:42px;padding:0;display:grid;place-items:center;align-content:center;gap:0;border-color:#3a5362;background:#142331}.dirgrid button b{font-size:18px;line-height:18px}.dirgrid button small{font-size:8px;color:#97abb7}.dirgrid button.sel{border-color:var(--cyan);background:#123239;color:var(--cyan);box-shadow:0 0 12px #54f3e12a}.dircenter{font:600 9px 'IBM Plex Mono',monospace;color:var(--cyan);letter-spacing:.05em}.destinationHint{font-size:8px;color:var(--muted);text-align:center}.arena:focus-visible{outline:3px solid var(--cyan);outline-offset:-4px}.control:focus-visible,.dirgrid button:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #a3fff4;outline-offset:2px}.control{min-height:74px;text-align:left;line-height:1.5}.control strong{font-size:17px}.combatOverlay .control{min-height:82px}
+@media(max-width:850px){.moveControls{grid-template-columns:1fr}.moveChoices{grid-template-columns:repeat(2,minmax(0,1fr))}.moveChoices>.eyebrow{grid-column:1/-1}.destination{border-left:0;border-top:1px solid var(--line);padding:12px 0 0}.dirgrid{grid-template-columns:58px 58px 58px;grid-template-rows:50px 50px 50px}.dirgrid button{width:58px;height:50px}.turnbar{align-items:flex-start}.turnclock{width:70px}.control{min-height:76px}}
+@media(max-width:420px){.moveChoices{grid-template-columns:1fr 1fr}.turncopy>span:last-child{font-size:9px}.turncopy strong{font-size:19px}.turnclock>span{font-size:26px}}
+'''
s=s.replace('@media(max-width:850px){.layout{grid-template-columns:1fr}',css+'@media(max-width:850px){.layout{grid-template-columns:1fr}',1)
p.write_text(s,encoding='utf-8')
